"""Prove complete original corridor chains before native separator dispatch.

Private side permissions are checked against the original incidence registry,
not against a successful mesh. Each traversal consumes every corridor and
intermediate patch exactly once, joining at the exact original junction ID.
Moving source vertices therefore needs no Python callback; changing topology
requires new declarations, and stale declarations fail explicitly.
"""
from . import curved_network_ownership_nodes as own
from . import curved_junction_nodes as boundary

c = boundary.c
MAX_RULES = 512


def row(g, inp, original, patch_status, values, port_owner, *, longitudinal_chains=False):
    compare = lambda a, b, op='EQUAL': own._compare(g, a, b, op)
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    rules = c._select(g, inp.outputs['Separator Owners'],
                      compare(c.named(g, 'st_sr_bundle_id', 'INT'), values['bundle_id']))
    role = c.named(g, 'st_sr_role', 'INT')
    kind = c.named(g, 'st_sr_kind', 'INT')
    owner = c.named(g, 'st_sr_owner', 'INT')
    count = c._count(g, rules)
    ok = compare(count, 4, 'GREATER_EQUAL')*compare(count, MAX_RULES, 'LESS_EQUAL')
    allowed = compare(role, 0, 'GREATER_EQUAL')*compare(role, 3, 'LESS_EQUAL')
    allowed = allowed*g.math('MAXIMUM', compare(kind, 0), compare(kind, 1))
    allowed = allowed*c.choose(g, compare(role, 2, 'GREATER_EQUAL'), compare(kind, 0), 1.)
    ok = ok*own._all(g, rules, allowed*own._exists(g, ['st_sr_'+k for k in ('bundle_id','role','kind','owner')]))
    if longitudinal_chains:
        from . import curved_separator_member_nodes as membership
        ok = ok*membership.valid(g, rules)
    terminals = [values[k] for k in ('a_head','a_tail','b_head','b_tail')]
    for at, port in enumerate(terminals):
        ok = ok*compare(port, 0, 'GREATER_EQUAL')*compare(port, c._count(g, original), 'LESS_THAN')
        for previous in terminals[:at]:ok = ok*(1.-compare(port, previous))
        sid = values['member_a' if at < 2 else 'member_b']
        expected = values['head_patch' if at % 2 == 0 else 'tail_patch']
        actual, found = port_owner(port)
        ok = ok*found*compare(actual, expected)
        if not longitudinal_chains or at % 2 == 0:
            ok = ok*compare(c._read(g, original, 'st_cj_street_id', port, 'INT'), sid)
    for side, label in ((2, 'head_patch'), (3, 'tail_patch')):
        cap = c._select(g, rules, compare(role, side))
        ok = ok*compare(c._count(g, cap), 1)*own._all(g, cap, compare(kind, 0)*compare(owner, values[label]))
    # An intermediate owner cannot be shared by the two member boundaries.
    middle = c._select(g, rules, compare(kind, 0)*compare(role, 2, 'LESS_THAN'))
    ok = ok*own._all(g, middle, compare(own._total(g, 1, owner), 1))
    for side, prefix in ((0, 'a'), (1, 'b')):
        sid = values['member_'+prefix]
        corridors = inp.outputs['Corridors']
        grants = c._select(g, rules, compare(role, side)*compare(kind, 1))
        members = (membership.routes(g, corridors, 'st_cs_street_id', grants) if longitudinal_chains else
                   c._select(g, corridors, compare(c.named(g, 'st_cs_street_id', 'INT'), sid)))
        n = c._count(g, members)
        middle = c._select(g, rules, compare(role, side)*compare(kind, 0))
        side_ok = compare(n, 0, 'GREATER_THAN')*compare(n, MAX_RULES//2, 'LESS_EQUAL')
        side_ok = side_ok*compare(c._count(g, grants), n)*compare(c._count(g, middle), n-1.)
        grant_ok = compare(owner, 0, 'GREATER_EQUAL')*compare(owner, c._count(g, corridors), 'LESS_THAN')
        grant_ok = grant_ok*compare(c._read(g, corridors, 'st_cs_street_id', owner, 'INT'),
                                   c.named(g, 'st_sr_street_id', 'INT') if longitudinal_chains else sid)
        side_ok = side_ok*own._all(g, grants, grant_ok*compare(own._total(g, 1, owner), 1))
        if longitudinal_chains:
            side_ok = side_ok*membership.ports_valid(g, members, original)
            # Closed sides cannot silently omit a generated external route
            # belonging to any of their original Streets.
            extra = membership.routes(g, inp.outputs['External Approaches'], 'st_ca_street_id', grants)
            side_ok = side_ok*compare(c._count(g, extra), 0)
        from . import curved_patch_provider_nodes as patches
        found, _ = patches._lookup(g, patch_status, patches.SITE, owner)
        middle_ok = found*(1.-compare(owner, values['head_patch']))*(1.-compare(owner, values['tail_patch']))
        side_ok = side_ok*own._all(g, middle, middle_ok*compare(own._total(g, 1, owner), 1))
        begin = g.node('GeometryNodeRepeatInput', 'Consume member '+prefix+' at exact original junctions')
        end = g.node('GeometryNodeRepeatOutput', 'Every corridor and intermediate owner exactly once')
        end.repeat_items.clear()
        for key in ('Corridors', 'Intermediate Owners'):end.repeat_items.new('GEOMETRY', key)
        end.repeat_items.new('INT', 'Port');end.repeat_items.new('BOOLEAN', 'Valid')
        begin.pair_with_output(end)
        g.bind(members, begin.inputs['Corridors']);g.bind(middle, begin.inputs['Intermediate Owners'])
        g.bind(values[prefix+'_head'], begin.inputs['Port']);g.bind(side_ok, begin.inputs['Valid'])
        g.bind(c.choose(g, side_ok, n, 0, 'INT'), begin.inputs['Iterations'])
        pool = begin.outputs['Corridors'];left = begin.outputs['Intermediate Owners']
        entry = begin.outputs['Port']
        first = c.named(g, 'st_cs_start_index', 'INT');last = c.named(g, 'st_cs_end_index', 'INT')
        match = g.math('MAXIMUM', compare(first, entry), compare(last, entry))
        step_ok = compare(c._stat(g, pool, match, 'Sum'), 1)
        chosen = c._stat(g, pool, match*index, 'Sum')
        start = c._read(g, pool, 'st_cs_start_index', chosen, 'INT')
        finish = c._read(g, pool, 'st_cs_end_index', chosen, 'INT')
        leave = c.choose(g, compare(start, entry), finish, start, 'INT')
        remaining = c._select(g, pool, 1.-compare(index, chosen))
        final = compare(begin.outputs['Iteration'], n-1.)
        junction = c._read(g, original, 'st_cj_junction_id', leave, 'INT')
        start_match = compare(c._read(g, original, 'st_cj_junction_id', first, 'INT'), junction)
        end_match = compare(c._read(g, original, 'st_cj_junction_id', last, 'INT'), junction)
        next_match = start_match+end_match
        next_ok = compare(c._stat(g, remaining, next_match, 'Sum'), 1)
        next_row = c._stat(g, remaining, next_match*index, 'Sum')
        next_port = c._sample(g, remaining, c.choose(g, start_match, first, last, 'INT'), next_row, 'INT')
        patch, found = port_owner(leave)
        patch_match = compare(owner, patch)
        next_ok = next_ok*found*compare(c._stat(g, left, patch_match, 'Sum'), 1)
        unused = c._select(g, left, 1.-patch_match)
        step_ok = step_ok*c.choose(g, final, compare(leave, values[prefix+'_tail']), next_ok)
        g.bind(remaining, end.inputs['Corridors'])
        g.bind(c.choose(g, final, left, unused, 'GEOMETRY'), end.inputs['Intermediate Owners'])
        g.bind(c.choose(g, final, leave, next_port, 'INT'), end.inputs['Port'])
        g.bind(c.V(g, begin.outputs['Valid'])*step_ok, end.inputs['Valid'])
        ok = ok*c.V(g, end.outputs['Valid'])*compare(end.outputs['Port'], values[prefix+'_tail'])
        ok = ok*compare(c._count(g, end.outputs['Corridors']), 0)*compare(c._count(g, end.outputs['Intermediate Owners']), 0)
    return ok


def permissions(g, inp, *, free_chains=False, regions=False):
    """No orphan permission can hide behind a missing or non-chain Bundle."""
    rules = inp.outputs['Separator Owners'];rows = inp.outputs['Separators']
    within = own._compare(g, c._count(g, rules), MAX_RULES*128, 'LESS_EQUAL')
    within = within*own._all(g, rules, own._exists(g, ['st_sr_'+k for k in ('bundle_id','role','kind','owner')]))
    # Accumulate by integer Bundle ID once, avoiding one table scan per rule.
    rules = c._store(g, rules, '_sc_bundle', c.named(g, 'st_sr_bundle_id', 'INT'), 'INT')
    rules = c._store(g, rules, '_sc_declaration', 0, 'INT')
    rules = c._store(g, rules, '_sc_rule', 1, 'INT')
    rows = c._store(g, rows, '_sc_bundle', c.named(g, 'st_sb_bundle_id', 'INT'), 'INT')
    declaration = own._compare(g,c.named(g,'st_sb_kind','INT'),2)
    if free_chains:
        declaration = g.math('MAXIMUM', declaration, own._compare(g,c.named(g,'st_sb_kind','INT'),3))
    if regions:
        declaration = g.math('MAXIMUM', declaration, own._compare(g,c.named(g,'st_sb_kind','INT'),4))
    rows = c._store(g, rows, '_sc_declaration', declaration, 'INT')
    rows = c._store(g, rows, '_sc_rule', 0, 'INT')
    # Keep the temporary accumulation domain non-empty. Blender 5.2 can leave
    # a null mesh component when joining two empty meshes after Store Named
    # Attribute, which crashes a downstream Domain Size node. This sentinel
    # has no rule/declaration and never enters authored or generated geometry.
    sentinel = c._store(g,c._line(g,1),'_sc_bundle',-1,'INT')
    sentinel = c._store(g,sentinel,'_sc_declaration',0,'INT')
    sentinel = c._store(g,sentinel,'_sc_rule',0,'INT')
    joined = boundary._join(g, rows, rules, sentinel)
    total = own._total(g, c.named(g,'_sc_declaration','INT'), c.named(g,'_sc_bundle','INT'))
    return within*own._all(g, joined, c.choose(g, c.named(g,'_sc_rule','INT'), own._compare(g,total,1), 1.))
